(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzt-sj-prepa-med-j8-ide3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzt-sj-prepa-med-j8-ide3\",\n \"titre\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 54,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J8_Medecine_IDE3_corrige_explique.pdf\",\n   \"sha256\": \"eba08dc4e7d44c6120dc7db9582e42538f4e9ec23d2069ee9f373b14f7e16604\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Médecine · Prépa D.E J8 (IDE3)\",\n     \"slug\": \"prepa-med-j8-ide3\",\n     \"pages\": \"\",\n     \"count\": 54,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Médecine\",\n     \"source\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__0\",\n       \"num\": \"1\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — Monsieur GUE Pascal est un patient diabétique âgé de 52 ans. Il présente les signes suivants : sueurs, tremblements, pâleur et troubles de la parole. Il est conscient et peut avaler. Après correction de l'épisode, un projet de soins infirmiers est envisagé.\",\n       \"text\": \"Les sueurs, tremblements, pâleur et troubles de la parole font partie des signes d'alerte de l'hypoglycémie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Sueurs, tremblements, pâleur, troubles de la parole sont des signes adrénergiques et neuroglucopéniques d'alerte de l'hypoglycémie ; le recueil de révision cite sueurs, pâleur, tremblements, tachycardie.\\n\\nSource : Documents de révision L3 Médecine, Diabète, QCM 15\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__1\",\n       \"num\": \"2\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — Monsieur GUE Pascal est un patient diabétique âgé de 52 ans. Il présente les signes suivants : sueurs, tremblements, pâleur et troubles de la parole. Il est conscient et peut avaler. Après correction de l'épisode, un projet de soins infirmiers est envisagé.\",\n       \"text\": \"Chez un adulte de 60 kg conscient, il faut 1 morceau de sucre, soit environ 5 grammes, pour le resucrage en cas d'hypoglycémie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le resucrage d'un adulte conscient se fait avec environ 15 g de sucre (≈ 3 morceaux de 5 g), et non un seul morceau. Le recueil de révision conseille d'ailleurs d'avoir « au moins 3 sucres » à portée de main.\\n\\nSource : Documents de révision L3 Médecine, Diabète, QCM 16 (explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__2\",\n       \"num\": \"3\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — Monsieur GUE Pascal est un patient diabétique âgé de 52 ans. Il présente les signes suivants : sueurs, tremblements, pâleur et troubles de la parole. Il est conscient et peut avaler. Après correction de l'épisode, un projet de soins infirmiers est envisagé.\",\n       \"text\": \"Après resucrage, la glycémie capillaire est contrôlée uniquement 24 heures plus tard.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après resucrage, on recontrôle la glycémie capillaire environ 15 minutes plus tard, puis on surveille ; attendre 24 h serait dangereux.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__3\",\n       \"num\": \"4\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — Monsieur GUE Pascal est un patient diabétique âgé de 52 ans. Il présente les signes suivants : sueurs, tremblements, pâleur et troubles de la parole. Il est conscient et peut avaler. Après correction de l'épisode, un projet de soins infirmiers est envisagé.\",\n       \"text\": \"Le diagnostic infirmier correspond à un jugement clinique sur les réactions du bénéficiaire de soins face à un problème de santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le diagnostic infirmier est un jugement clinique sur les réactions d'une personne à un problème de santé réel ou potentiel ; il relève du rôle propre de l'infirmier.\\n\\nSource : Documents de révision L3 Médecine, Soins infirmiers (diagnostic infirmier) (explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La présence d'une ligne dans la fenêtre C et d'une ligne, même faible, dans la fenêtre T rend le TDR positif.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lecture du TDR : une ligne en C et une ligne en T, même faible, = test positif (paludisme à P. falciparum). Pas de ligne en C = test invalide.\\n\\nSource : Documents de révision L3 Médecine, Paludisme, QCM 11 à 14\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__5\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Monsieur KOUASSI Jean, âgé de 32 ans, est admis aux urgences médicales de l'EPHR de Man pour une fièvre évoluant depuis trois jours, associée à des céphalées, des vomissements et une altération progressive de l'état général. À l'accueil, sa température est à 40 °C. Selon son accompagnant, il a présenté deux épisodes de convulsions généralisées avant son arrivée à l'hôpital. À l'examen, il est obnubilé et ne répond pas correctement aux questions. Le test de diagnostic rapide (TDR) du paludisme réalisé en urgence montre une ligne dans la fenêtre de contrôle C et une ligne faiblement colorée dans la fenêtre T. La microscopie (goutte épaisse/frottis sanguin) n'est pas disponible immédiatement.\",\n       \"text\": \"Les convulsions répétées et l'obnubilation sont-elles des signes de gravité du paludisme ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les convulsions multiples et les troubles de la conscience (obnubilation, coma) font partie des signes cliniques de gravité du paludisme.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 4-2-1 ; Cours de pathologies tropicales L1 (INFAS Daloa), § 4-2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__6\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Monsieur KOUASSI Jean, âgé de 32 ans, est admis aux urgences médicales de l'EPHR de Man pour une fièvre évoluant depuis trois jours, associée à des céphalées, des vomissements et une altération progressive de l'état général. À l'accueil, sa température est à 40 °C. Selon son accompagnant, il a présenté deux épisodes de convulsions généralisées avant son arrivée à l'hôpital. À l'examen, il est obnubilé et ne répond pas correctement aux questions. Le test de diagnostic rapide (TDR) du paludisme réalisé en urgence montre une ligne dans la fenêtre de contrôle C et une ligne faiblement colorée dans la fenêtre T. La microscopie (goutte épaisse/frottis sanguin) n'est pas disponible immédiatement.\",\n       \"text\": \"En l'absence de microscopie immédiatement disponible, il faut attendre la goutte épaisse avant de commencer la prise en charge d'un paludisme grave suspecté.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant des signes de gravité, on ne retarde pas le traitement : un TDR positif suffit pour débuter la prise en charge du paludisme grave ; au niveau périphérique on fait le TDR puis un traitement de pré-transfert.\\n\\nSource : Documents de révision L3 Médecine, Paludisme, QCM 3 et QCD 23 (« tout TDR positif doit faire l'objet d'un traitement »)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__7\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Monsieur KOUASSI Jean, âgé de 32 ans, est admis aux urgences médicales de l'EPHR de Man pour une fièvre évoluant depuis trois jours, associée à des céphalées, des vomissements et une altération progressive de l'état général. À l'accueil, sa température est à 40 °C. Selon son accompagnant, il a présenté deux épisodes de convulsions généralisées avant son arrivée à l'hôpital. À l'examen, il est obnubilé et ne répond pas correctement aux questions. Le test de diagnostic rapide (TDR) du paludisme réalisé en urgence montre une ligne dans la fenêtre de contrôle C et une ligne faiblement colorée dans la fenêtre T. La microscopie (goutte épaisse/frottis sanguin) n'est pas disponible immédiatement.\",\n       \"text\": \"Au niveau hospitalier, l'évaluation initiale doit notamment rechercher une hypoglycémie et une atteinte rénale, en plus de l'évaluation clinique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le bilan initial doit rechercher l'hypoglycémie et l'insuffisance rénale, qui font partie des critères biologiques de gravité.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 4-2-2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__8\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Monsieur KOUASSI Jean, âgé de 32 ans, est admis aux urgences médicales de l'EPHR de Man pour une fièvre évoluant depuis trois jours, associée à des céphalées, des vomissements et une altération progressive de l'état général. À l'accueil, sa température est à 40 °C. Selon son accompagnant, il a présenté deux épisodes de convulsions généralisées avant son arrivée à l'hôpital. À l'examen, il est obnubilé et ne répond pas correctement aux questions. Le test de diagnostic rapide (TDR) du paludisme réalisé en urgence montre une ligne dans la fenêtre de contrôle C et une ligne faiblement colorée dans la fenêtre T. La microscopie (goutte épaisse/frottis sanguin) n'est pas disponible immédiatement.\",\n       \"text\": \"Quelle classification est la plus appropriée au vu des éléments du cas ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Cas présumé de paludisme simple, car la microscopie manque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Paludisme simple, car la fièvre est le symptôme principal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Paludisme grave suspecté, avec TDR positif et signes neurologiques de gravité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Absence de paludisme, car le résultat du TDR doit être confirmé par deux tests\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Paludisme grave suspecté, avec TDR positif et signes neurologiques de gravité\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Fièvre + TDR positif + convulsions répétées et obnubilation (signes neurologiques de gravité) = paludisme grave.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 4-2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__9\",\n       \"num\": \"10\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Monsieur KOUASSI Jean, âgé de 32 ans, est admis aux urgences médicales de l'EPHR de Man pour une fièvre évoluant depuis trois jours, associée à des céphalées, des vomissements et une altération progressive de l'état général. À l'accueil, sa température est à 40 °C. Selon son accompagnant, il a présenté deux épisodes de convulsions généralisées avant son arrivée à l'hôpital. À l'examen, il est obnubilé et ne répond pas correctement aux questions. Le test de diagnostic rapide (TDR) du paludisme réalisé en urgence montre une ligne dans la fenêtre de contrôle C et une ligne faiblement colorée dans la fenêtre T. La microscopie (goutte épaisse/frottis sanguin) n'est pas disponible immédiatement.\",\n       \"text\": \"Quelle conduite initiale est la plus appropriée aux urgences de l'EPHR de Man ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Attendre la microscopie avant toute mesure thérapeutique, même si l'état neurologique est altéré\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faire ressortir le patient après un antipyrétique et programmer une consultation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prescrire une CTA orale et attendre la disparition de la fièvre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hospitaliser, assurer la stabilisation et la surveillance, évaluer rapidement la glycémie et les fonctions d'organes, puis débuter sans retard le traitement adapté au paludisme grave\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Hospitaliser, assurer la stabilisation et la surveillance, évaluer rapidement la glycémie et les fonctions d'organes, puis débuter sans retard le traitement adapté au paludisme grave\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le paludisme grave est une urgence : hospitalisation, stabilisation, bilan (glycémie, fonctions d'organes) et traitement parentéral sans retard. Le traitement oral par CTA est réservé au paludisme simple.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 5-1-2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__10\",\n       \"num\": \"11\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Monsieur KOUASSI Jean, âgé de 32 ans, est admis aux urgences médicales de l'EPHR de Man pour une fièvre évoluant depuis trois jours, associée à des céphalées, des vomissements et une altération progressive de l'état général. À l'accueil, sa température est à 40 °C. Selon son accompagnant, il a présenté deux épisodes de convulsions généralisées avant son arrivée à l'hôpital. À l'examen, il est obnubilé et ne répond pas correctement aux questions. Le test de diagnostic rapide (TDR) du paludisme réalisé en urgence montre une ligne dans la fenêtre de contrôle C et une ligne faiblement colorée dans la fenêtre T. La microscopie (goutte épaisse/frottis sanguin) n'est pas disponible immédiatement.\",\n       \"text\": \"Quelle dose d'artésunate injectable est indiquée chez l'adulte pour le traitement du paludisme grave ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"3 mg/kg par voie orale deux fois par jour pendant trois jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2,4 mg/kg à H0, H12 et H24 le premier jour, puis toutes les 24 heures de J2 à J7\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1,2 mg/kg à H0\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"4 mg/kg en intramusculaire toutes les six heures pendant 24 heures\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 2,4 mg/kg à H0, H12 et H24 le premier jour, puis toutes les 24 heures de J2 à J7\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Artésunate injectable : 2,4 mg/kg en IV à H0, H12 et H24 le 1er jour, puis 2,4 mg/kg toutes les 24 h de J2 à J7.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 5-1-2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__11\",\n       \"num\": \"12\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Monsieur KOUASSI Jean, âgé de 32 ans, est admis aux urgences médicales de l'EPHR de Man pour une fièvre évoluant depuis trois jours, associée à des céphalées, des vomissements et une altération progressive de l'état général. À l'accueil, sa température est à 40 °C. Selon son accompagnant, il a présenté deux épisodes de convulsions généralisées avant son arrivée à l'hôpital. À l'examen, il est obnubilé et ne répond pas correctement aux questions. Le test de diagnostic rapide (TDR) du paludisme réalisé en urgence montre une ligne dans la fenêtre de contrôle C et une ligne faiblement colorée dans la fenêtre T. La microscopie (goutte épaisse/frottis sanguin) n'est pas disponible immédiatement.\",\n       \"text\": \"Quel examen biologique est particulièrement important à réaliser rapidement devant ce tableau, en complément du test parasitologique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Glycémie, afin de dépister notamment une hypoglycémie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sérologie palustre IgG comme examen de confirmation immédiate\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Groupe sanguin uniquement, sans autre bilan urgent\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Glycémie, afin de dépister notamment une hypoglycémie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hypoglycémie (< 0,40 g/l) est un critère biologique de gravité et une complication à corriger en urgence (sérum glucosé hypertonique).\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 4-2-2 ; Cours de pathologies tropicales L1 (INFAS Daloa), § 7-4\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__12\",\n       \"num\": \"13\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Monsieur KOUASSI Jean, âgé de 32 ans, est admis aux urgences médicales de l'EPHR de Man pour une fièvre évoluant depuis trois jours, associée à des céphalées, des vomissements et une altération progressive de l'état général. À l'accueil, sa température est à 40 °C. Selon son accompagnant, il a présenté deux épisodes de convulsions généralisées avant son arrivée à l'hôpital. À l'examen, il est obnubilé et ne répond pas correctement aux questions. Le test de diagnostic rapide (TDR) du paludisme réalisé en urgence montre une ligne dans la fenêtre de contrôle C et une ligne faiblement colorée dans la fenêtre T. La microscopie (goutte épaisse/frottis sanguin) n'est pas disponible immédiatement.\",\n       \"text\": \"Si le TDR était négatif et que la suspicion clinique persistait, quelle démarche correspondrait aux recommandations ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Administrer systématiquement une CTA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Écarter définitivement la suspicion du paludisme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rechercher une autre cause de fièvre et réaliser une GE/FS si le patient reste suspect ou si les symptômes persistent\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Utiliser un TDR HRP2 répété comme seul examen de suivi post-thérapeutique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Rechercher une autre cause de fièvre et réaliser une GE/FS si le patient reste suspect ou si les symptômes persistent\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"TDR négatif avec suspicion persistante : rechercher une autre cause de fièvre et faire la goutte épaisse/frottis, examen de référence. Le TDR HRP2 ne sert pas à évaluer le traitement (antigène persistant).\\n\\nSource : Documents de révision L3 Médecine, Paludisme, QCM 23 et QCD 17\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel ensemble correspond aux mécanismes physiopathologiques de la crise d'asthme ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Obstruction vasculaire pulmonaire par thrombus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Œdème bronchique, contraction musculaire lisse et hypersécrétion de mucus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fibrose pleurale, épanchement et matité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Destruction alvéolaire isolée sans bronchospasme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Œdème bronchique, contraction musculaire lisse et hypersécrétion de mucus\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Mécanismes de l'asthme : œdème bronchique, contraction des muscles lisses bronchiques (bronchospasme) et hypersécrétion de mucus.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Asthme, § 3.2 Physiopathologie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel mécanisme contribue à l'hypoxémie lors d'une pneumonie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'augmentation de la ventilation des zones atteintes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le mucus augmente la surface d'échange\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La plèvre absorbe tout l'oxygène\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'exsudat alvéolaire gêne la ventilation et la diffusion des gaz\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. L'exsudat alvéolaire gêne la ventilation et la diffusion des gaz\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Dans la pneumonie, la réaction inflammatoire forme un exsudat dans les alvéoles ; certaines zones ne sont plus ventilées, d'où les troubles de la ventilation et de la diffusion et l'hypoxémie.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Pneumonie franche lobaire aiguë, physiopathologie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle étape appartient à l'élaboration du projet de soins ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Recueil et analyse des données\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Absence de planification\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Suppression de la traçabilité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Abandon de l'évaluation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Recueil et analyse des données\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le projet de soins commence par le recueil et l'analyse des données, puis diagnostic, objectifs, actions et évaluation.\\n\\nSource : Documents de révision L3 Médecine, Soins infirmiers, QCM 2 et 7\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lorsque les objectifs du projet de soins ne sont pas atteints, quelle est la conduite à tenir infirmière ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réévaluer la situation sans rien modifier\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Réévaluer la situation et adapter les interventions\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Supprimer le diagnostic infirmier sans réévaluation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Arrêter tous les soins\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Réévaluer la situation et adapter les interventions\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Si les objectifs ne sont pas atteints, on réévalue la situation et on réajuste les interventions (dernière étape de la démarche de soins).\\n\\nSource : Documents de révision L3 Médecine, Soins infirmiers, QCM 2 D (« évaluation des actions en vue des réajustements nécessaires »)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un diagnostic infirmier de risque est approprié lorsque :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le problème est déjà manifestement installé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des facteurs de risque existent sans manifestations du problème\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le diagnostic médical est inconnu\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Seules des manifestations sont présentes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Des facteurs de risque existent sans manifestations du problème\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un diagnostic infirmier de risque (problème potentiel) se pose quand des facteurs de risque existent sans que le problème soit encore manifeste.\\n\\nSource : Documents de révision L3 Médecine, Soins infirmiers, QCM 8 (problème potentiel, facteurs de risque)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle constitue une donnée d'indépendance chez un client hypertendu ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le client ne peut pas satisfaire seul ses besoins fondamentaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le client connaît les signes cliniques\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le client refuse toute information\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le client ne respecte pas le régime hyposodé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le client refuse toute information\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une donnée d'indépendance est ce que la personne fait ou sait par elle-même (ex. : « le client connaît les signes cliniques »). Refuser toute information, ne pas respecter le régime ou ne pas pouvoir satisfaire seul ses besoins sont des données de dépendance.\\n\\nSource : (explication hors cours du projet : modèle de V. Henderson)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pyrosis désigne :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une brûlure rétrosternale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une douleur à la déglutition\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un vomissement de sang noirâtre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une difficulté à avaler les liquides\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Une brûlure rétrosternale\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le pyrosis est une brûlure épigastrique à irradiation rétrosternale ascendante ; c'est l'expression typique du reflux gastro-œsophagien.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Reflux gastro-œsophagien, § 3.2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel délai de jeûne est indiqué avant une FOGD (fibroscopie œso-gastro-duodénale) ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2 à 3 heures\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6 à 8 heures\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"24 à 36 heures\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"30 à 60 minutes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 6 à 8 heures\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Avant une FOGD, le patient doit être à jeun depuis au moins 6 heures (6 à 8 h) pour que l'estomac soit vide et éviter l'inhalation.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ascite est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une accumulation de liquide dans la plèvre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une accumulation pathologique de liquide dans la cavité péritonéale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une dilatation des voies biliaires\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une inflammation de la muqueuse gastrique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une accumulation pathologique de liquide dans la cavité péritonéale\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'ascite est une accumulation (épanchement) de liquide dans la cavité péritonéale.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Cirrhose (ascite = épanchement de liquide dans le péritoine)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle voie de transmission caractérise principalement l'hépatite A ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Transmission périnatale, principalement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Voie féco-orale, souvent l'eau contaminée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Transmission par piqûre de moustique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Voie sexuelle, exclusivement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Voie féco-orale, souvent l'eau contaminée\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'hépatite A se transmet par voie féco-orale (eau, aliments souillés, mains sales).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Hépatites virales, Virus de l'hépatite A\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel objectif est associé au lavage de vessie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Traiter les causes d'insuffisance rénale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Augmenter directement la filtration glomérulaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Évacuer les copeaux ou caillots présents dans la vessie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Mesurer la clairance de la créatinine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Évacuer les copeaux ou caillots présents dans la vessie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le lavage vésical (sur sonde à double courant) sert à évacuer les copeaux et caillots présents dans la vessie, par exemple après chirurgie prostatique ou en cas d'hématurie.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle des propositions suivantes est une cause post-rénale d'insuffisance rénale aiguë ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une exposition à un aminoside\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une obstruction des voies urinaires par calcul\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une hémorragie aiguë\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un choc septique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une obstruction des voies urinaires par calcul\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'IRA post-rénale (obstructive) est due à un obstacle sur les voies urinaires (calcul, adénome…). Hémorragie et choc septique = causes pré-rénales (fonctionnelles) ; aminoside = cause rénale (toxique).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel élément figure dans le suivi d'un client sous PrEP ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dépistage du VIH à un mois puis tous les trois mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aucun dépistage du VIH après l'initiation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Contrôle quotidien de la créatinine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Arrêt des conseils d'observance après la première visite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Dépistage du VIH à un mois puis tous les trois mois\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le suivi d'un client sous PrEP comprend un dépistage VIH régulier (à un mois puis tous les trois mois), le suivi de la fonction rénale (TDF) et le conseil d'observance.\\n\\nSource : Cours VIH Licence 2 (TARV), PrEP (protocole TDF + 3TC) (explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la période d'incubation de la dengue ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1 à 2 jours avant les signes et 7 jours après\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"5 à 8 jours en moyenne\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"7 à 15 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"De 0 à 14 jours, en moyenne 6 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 5 à 8 jours en moyenne\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Pour la dengue classique, le cours indique une incubation silencieuse de 5 à 8 jours en moyenne. Remarque : Le même cours cite aussi « 4 à 7 jours » et « 2 à 7 jours » ; la proposition « 0 à 14 jours, moyenne 6 jours » correspond à la COVID-19.\\n\\nSource : Cours de maladies infectieuses et parasitaires, La dengue, § 3 Signes cliniques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel signe est cité parmi les manifestations cliniques de la COVID-19 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dysosmie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Tache rosée lenticulaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Angine de Duguet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Inflammation de l'orifice du canal de Sténon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Dysosmie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La dysosmie (perte d'odorat) et la dysgueusie font partie des signes d'invasion de la COVID-19. Taches rosées et angine de Duguet = fièvre typhoïde ; orifice du Sténon = oreillons.\\n\\nSource : Cours de maladies infectieuses et parasitaires, COVID-19, § Invasion\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Monsieur Konan reçoit une perfusion de 250 ml de SGI à 5 %. Quelle est la quantité de matière en grammes (g) de glucose que vous lui avez administrée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"12,5 grammes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"125 grammes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"250 grammes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"15,5 grammes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 12,5 grammes\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"SGI 5 % = 5 g pour 100 ml → 250 ml contiennent 12,5 g de glucose.\\n\\nSource : Calcul de concentration\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le débit d'une perfusion en maintien est de 10 gouttes par minute en 2 heures. Indiquez le volume de soluté qui est passé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"120 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"150 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"75 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"60 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 60 ml\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Volume = 10 gouttes/min × 120 min / 20 = 60 ml.\\n\\nSource : Calcul de débit (1 ml = 20 gouttes)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hypertension artérielle est définie par une pression artérielle systolique supérieure ou égale à 140 mmHg et/ou une pression artérielle diastolique supérieure ou égale à 90 mmHg constatée au cours d'au moins deux consultations différentes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"HTA = PAS ≥ 140 mmHg et/ou PAD ≥ 90 mmHg, mesurées à plusieurs reprises (au moins deux consultations).\\n\\nSource : Documents de révision L3 Médecine, Maladies cardiovasculaires, QCD 6 (seuil 140/90)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le tabagisme, l'obésité, la sédentarité et le stress figurent parmi les facteurs de risque de l'hypertension artérielle secondaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Tabac, obésité, sédentarité, stress sont des facteurs de risque de l'HTA essentielle (primitive). L'HTA secondaire a une cause précise (rénale, endocrinienne, coarctation…). Remarque : Dans le sujet, l'énoncé se termine par le mot « Faux », qui donne la réponse.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une pression artérielle doit être mesurée immédiatement après la prise de café ou de tabac afin d'obtenir une valeur représentative.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La pression artérielle se mesure au repos, après 5 à 10 min, à distance (environ 30 min) du café et du tabac, qui l'élèvent transitoirement.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'insuffisance veineuse, les douleurs sont majorées par l'orthostatisme et la chaleur.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans l'insuffisance veineuse, les douleurs sont majorées par l'orthostatisme (position debout), la chaleur et les cycles menstruels.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Insuffisance veineuse, § 4 Signes fonctionnels\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pression artérielle systolique (PAS) correspond à la pression du sang quand le cœur se détend et reprend son volume, ce qui permet aux cavités cardiaques de se remplir.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La phrase décrit la diastole (relâchement et remplissage des cavités) : c'est la pression artérielle diastolique. La PAS correspond à la contraction (systole).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une veine est un vaisseau composé de deux couches.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours dit : « une veine est un vaisseau composé de trois couches » ; la couche interne porte les clapets valvulaires. « Deux couches » est donc faux.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Insuffisance veineuse, rappel anatomique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'altération des clapets valvulaires (de la veine) est à l'origine des insuffisances veineuses ou varices.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"« L'altération des clapets valvulaires est à l'origine des insuffisances veineuses ou varices. »\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Insuffisance veineuse, rappel anatomique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prévention de la phlébite comprend notamment la mobilisation active, le lever précoce et les bas de contention.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La prévention de la phlébite repose sur le lever précoce, la mobilisation active des membres et la contention élastique (bas), ± anticoagulants préventifs.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Phlébite / insuffisance veineuse (contention pour stimuler le retour veineux)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'insuffisance cardiaque gauche, la défaillance du ventricule gauche entraîne une augmentation de la perfusion rénale et une oligurie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La défaillance du VG entraîne en aval une diminution (et non une augmentation) du débit de perfusion des tissus, notamment des reins, d'où l'oligurie.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Insuffisance cardiaque gauche, § 2 Physiopathologie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le patient atteint d'œdème aigu du poumon cardiogénique doit être installé en position demi-assise, les jambes pendantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Installer le patient en position demi-assise, jambes pendantes : cela diminue le retour veineux et soulage la dyspnée.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Œdème aigu du poumon, conduite à tenir\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le poumon gauche comporte trois lobes et le poumon droit deux lobes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le poumon droit a trois lobes (deux scissures) et le poumon gauche deux lobes (une scissure) : l'affirmation est inversée.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Rappel anatomique de l'appareil respiratoire\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une fréquence respiratoire supérieure à 35 cycles/min et une saturation en oxygène inférieure à 90 % figurent parmi les signes de gravité de l'asthme.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Fréquence respiratoire > 30-35/min et SpO2 < 90 % font partie des signes de gravité d'une crise d'asthme (avec tachycardie > 120, difficulté à parler, cyanose). Remarque : Le cours cite le seuil de 30 cycles/min ; le sujet parle de 35.\\n\\nSource : Documents de révision L3 Médecine, Asthme, QCM 7 et 12 ; Cours de médecine IDE 2 (INFAS, actualisé 2020), signes de gravité respiratoires\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La miliaire tuberculeuse correspond à une dissémination du germe dans l'organisme.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La miliaire tuberculeuse est la dissémination hématogène du bacille dans l'organisme, avec de multiples granulomes de la taille d'un grain de mil.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Tuberculose, miliaire\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'aérosolthérapie permet de fluidifier les sécrétions bronchiques et de bronchodilater les voies respiratoires.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'aérosolthérapie humidifie et fluidifie les sécrétions et permet d'administrer des bronchodilatateurs (β2 mimétiques) dans les voies respiratoires.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Asthme (aérosols de β2 mimétiques) et soins respiratoires\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'hémorragie méningée, la surveillance neurologique porte sur la conscience, la motricité et les pupilles.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans l'hémorragie méningée, la surveillance neurologique porte sur la conscience (Glasgow), les pupilles et la motricité (déficit), en plus des constantes.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Virginia Henderson considère les 14 besoins fondamentaux comme hiérarchisés selon un ordre fixe de priorité.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Pour Virginia Henderson, les 14 besoins sont interdépendants et leur priorité varie selon la personne et la situation : il n'y a pas d'ordre fixe de priorité. Remarque : Dans le sujet, l'énoncé se termine par le mot « Faux », qui donne la réponse.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La gastrite chronique est toujours symptomatique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La gastrite est une définition histologique ; elle peut être longtemps asymptomatique (ex. gastrite chronique à H. pylori découverte à l'endoscopie).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Ulcère gastro-duodénal et gastrite\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le virus de l'hépatite B est transmis par voie sexuelle, périnatale et par contact avec du sang contaminé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le VHB se transmet par voie sexuelle, par le sang (injections, matériel souillé) et de la mère à l'enfant (périnatale).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Hépatites virales, VHB ; Documents de révision L3 Médecine, Hépatites QCM 4\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les IST (infections sexuellement transmissibles) peuvent être d'origine bactérienne, parasitaire, mycosique ou virale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les agents des maladies infectieuses (et des IST) sont des bactéries, virus, parasites et champignons (mycoses).\\n\\nSource : Cours de maladies infectieuses et parasitaires, Généralités, § 1.2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La colique néphrétique correspond à un syndrome douloureux paroxystique lié à une distension brutale des voies urinaires.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La colique néphrétique est une douleur lombaire paroxystique due à la mise en tension brutale des voies urinaires en amont d'un obstacle (calcul le plus souvent).\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Lithiase urinaire – colique néphrétique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prévention primaire des IST comprend notamment la réduction du nombre de partenaires et l'utilisation des préservatifs.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La prévention primaire des IST repose sur le changement de comportement : abstinence, fidélité, réduction du nombre de partenaires, préservatifs.\\n\\nSource : Documents de révision L3 Médecine, VIH/IST, QCD 28 et QCM 17\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les inhibiteurs de fusion et d'entrée bloquent la production de l'ADN du VIH.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les inhibiteurs d'entrée et de fusion empêchent le virus de pénétrer dans la cellule (fixation à gp41). Ce sont les inhibiteurs de la reverse transcriptase qui bloquent la conversion de l'ARN viral en ADN.\\n\\nSource : Cours VIH Licence 2 (TARV), Mode d'action des ARV\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__52\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la fièvre typhoïde, au premier septénaire, la fièvre est en plateau et s'accompagne d'une dissociation du pouls et de la température.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Au 1er septénaire, la fièvre est ascendante, en oscillations (« en escalier »). Le plateau avec dissociation pouls-température caractérise le 2e septénaire.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, § 2.2 et 2.3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j8-ide3__53\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Schistosoma haematobium est l'agent pathogène de la bilharziose uro-génitale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"S. haematobium est l'agent de la bilharziose uro-génitale (hématurie terminale, cystite, complications génitales).\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Bilharzioses, § 2-3-1 et 5-4\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J8 (IDE3)\",\n       \"sourceFile\": \"J8_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
